#!/usr/bin/env python3
"""Write docs/bundled-app-catalog.md from shared/program-manifests/catalog.json.

Development-only. Usage: gen_catalog_doc.py   (paths resolved from this file)
"""
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))


def main():
    cat = json.load(open(os.path.join(ROOT, 'shared', 'program-manifests', 'catalog.json')))['programs']
    out = ['# Bundled application catalog', '',
           'Generated by `tools/resource-packaging/gen_catalog_doc.py` from',
           '`shared/program-manifests/catalog.json` (do not edit by hand).', '',
           'Original HolyC mode executes the bundled source through the sandboxed runtime.',
           'Native mode executes its compiled Swift/Kotlin implementation; availability is separate',
           'from functional verification. Status comes from `shared/program-manifests/compatibility.json`:',
           '**runs** = curated executable status; **partial** = a recorded limitation;',
           '**unsupported** = no advertised working launch (original source remains accessible).',
           'These statuses do not certify every original feature. See the',
           '[restoration report](games-preservation/SOURCE_ONLY_COMPLETION.md) and',
           '[actual verification](games-preservation/VERIFICATION.md) for tested scope.', '']
    built_in = [
        ('Terminal', 'HolyC command line (JIT-style statements, Dir, Cd, Type, Ed, #include ...)'),
        ('HolyC Editor', 'syntax-highlighting editor; RUN, SAVE, UNDO/REDO; drafts survive restarts'),
        ('Files', 'browse the C: drive; new file/folder, rename, copy, move, delete, restore originals'),
        ('Games', 'original V5.03 icon menu and a separate catalog of supported programs and demos'),
        ('Documentation', 'DolDoc viewer for the original TempleOS docs (links, macros, colours)'),
        ('God Words', 'native port of Adam/God/HolySpirit.HC: random words and Bible passages'),
        ('Paint', '16-colour drawing; saves TempleOS .GR images'),
        ('Settings', 'sound, desktop colour, display scale, crisp scaling, storage use'),
        ('About & Credits', 'credits to Terry A. Davis; independence and privacy statements'),
    ]
    out += ['## Built-in apps (native, both platforms)', '', '| App | What it does |', '|---|---|']
    out += [f'| {a} | {d} |' for a, d in built_in]
    out.append('')
    names = {'game': 'Games', 'demo': 'Graphics demos', 'app': 'Applications', 'sound': 'Sound programs', 'example': 'HolyC examples'}
    for cat_id in ('game', 'app', 'sound', 'demo', 'example'):
        progs = sorted((p for p in cat if p['category'] == cat_id), key=lambda p: p['title'].lower())
        counts = {}
        for p in progs:
            counts[p['status']] = counts.get(p['status'], 0) + 1
        summary = ', '.join(f'{v} {k}' for k, v in sorted(counts.items()))
        out += [f'## {names[cat_id]} ({len(progs)}: {summary})', '',
                '| Title | Path | Controls | Status | Execution modes | Note |', '|---|---|---|---|---|---|']
        for p in progs:
            modes=p.get('executionModes',{})
            availability='; '.join(f'{label}: {modes.get(key,"unavailable")}' for key,label in [('holyC','HolyC'),('nativeSwift','Swift'),('nativeKotlin','Kotlin')])
            out.append(f"| {p['title']} | `{p['path']}` | {', '.join(p['controls']) or '-'} | {p['status']} | {availability} | {p['note']} |")
        out.append('')
    out += ['## Provenance', '',
            'Games, demos and applications: TempleOS V5.03 by Terry A. Davis (public domain),',
            'byte-identical to the official ISO, except six files in which offensive content is censored or redacted',
            '(`content-moderation/CONTENT_MODERATION.md`). HolyC examples: written for this project.',
            'See `licensing-and-provenance.md`.', '']
    open(os.path.join(ROOT, 'docs', 'bundled-app-catalog.md'), 'w').write('\n'.join(out))
    print('wrote docs/bundled-app-catalog.md')


if __name__ == '__main__':
    main()
